def fill(g,o):
    H,W=len(g),len(g[0])
    for i in range(H):
        for j in range(W):
            if g[i][j]==0: continue
            v=g[i][j]; cnt={}
            for dr,dc in ((1,1),(1,-1)):
                r,c=i+dr,j+dc
                if 0<=r<H and 0<=c<W: cnt[g[r][c]]=cnt.get(g[r][c],0)+1
            # fill 0-cell surrounded by two diagonal neighbors of same color
            if g[i][j]==0 and 2==sum(1 for dr,dc in ((1,1),(1,-1)) if 0<=i+dr<H and 0<=j+dc<W and g[i+dr][j+dc]==v):
                o[i][j]=v
    return o
