import json
from collections import deque
def f(g):
    R,C=len(g),len(g[0])
    seen=[[False]*C for _ in range(R)]; out=[r[:] for r in g]
    for i in range(R):
        for j in range(C):
            if not seen[i][j] and g[i][j]:
                col=g[i][j]; q=deque([(i,j)]); seen[i][j]=True; cells=[]
                while q:
                    r_,c_=q.popleft(); cells.append((r_,c_))
                    for dr in(-1,0,1):
                        for dc in(-1,0,1):
                            rr,cc=r_+dr,c_+dc
                            if 0<=rr<R and 0<=cc<C and not seen[rr][cc] and g[rr][cc]==col:
                                seen[rr][cc]=True; q.append((rr,cc))
                rows=[r for r,_ in cells]; cols=[c for _,c in cells]
                for r in range(min(rows),max(rows)+1):
                    for c in range(min(cols),max(cols)+1):
                        out[r][c]=col
    return out
