T=load()
def comps_of(a,bg=None):
    H,W=len(a),len(a[0]); seen=[[False]*W for _ in range(H)]; out=[]
    for r in range(H):
        for c in range(W):
            if a[r][c]!=bg and not seen[r][c]:
                stack=[(r,c)]; seen[r][c]=True; cells=[]
                while stack:
                    y,x=stack.pop(); cells.append((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and a[ny][nx]!=bg and not seen[ny][nx]:
                            seen[ny][nx]=True; stack.append((ny,nx))
                out.append(cells)
    return out
def solve(a):
    H,W=len(a),len(a[0])
    cnt=collections.Counter(v for r in a for v in r)
    bg=max(cnt,key=cnt.get)
    cs=comps_of(a,bg)
    tile=max(cs,key=lambda c: len(set(a[y][x] for y,x in c)))
    rs=[y for y,x in tile]; cls=[x for y,x in tile]
    r0=min(rs); c0=min(cls); h=max(rs)-min(rs)+1; w=max(cls)-min(cls)+1
    pat=[[a[r0+i][c0+j] for j in range(w)] for i in range(h)]
    tileset=set(tile)
    out=[row[:] for row in a]
    for r in range(H):
        for c in range(W):
            if a[r][c]!=bg and (r,c) not in tileset:
                for i in range(h):
                    for j in range(w):
                        nr=r-(h-1)//2+i; nc=c-(w-1)//2+j
                        if 0<=nr<H and 0<=nc<W:
                            out[nr][nc]=pat[i][j]
    return out
