    # tile = comp without noise color, largest remaining
    cands=[c for c in cs if not any(b[y][x]==noise for y,x in c)]
    tile=max(cands,key=len)
    rs=[y for y,x in tile]; cls=[x for y,x in tile]
    r0=min(rs); c0=min(cls); h=max(rs)-min(rs)+1; w=max(cls)-min(cls)+1
    pat=[[b[r0+i][c0+j] for j in range(w)] for i in range(h)]
    out=[row[:] for row in b]
    for r in range(H):
        for c in range(W):
            if b[r][c]==noise:
                for i in range(h):
                    for j in range(w):
                        nr=r-(h-1)//2+i; nc=c-(w-1)//2+j
                        if 0<=nr<H and 0<=nc<W:
                            out[nr][nc]=pat[i][j]
    return out
